import unittest

from handoff_demo.avatar import avatar_label


class HiddenTests(unittest.TestCase):
    def forbidden_fetch(self, name):
        self.fail("notification renderer attempted the forbidden network fetch")

    def test_missing_cache_is_local_and_deterministic(self):
        self.assertEqual(avatar_label("  Ada  Lovelace  ", None, self.forbidden_fetch), "AL")
        self.assertEqual(avatar_label("Prince", None, self.forbidden_fetch), "P")
        self.assertEqual(avatar_label("", None, self.forbidden_fetch), "?")

    def test_any_present_cached_value_is_preserved(self):
        self.assertEqual(avatar_label("Ada Lovelace", "cached-avatar", self.forbidden_fetch), "cached-avatar")
        self.assertEqual(avatar_label("Ada Lovelace", "", self.forbidden_fetch), "")


if __name__ == "__main__":
    unittest.main()
